"""Local reversible prompt redaction."""

from enum import Enum

# The module is generated by the wheel build.
from ._native import Keybox  # pylint: disable=import-error


class SecretType(str, Enum):
    """Secret categories accepted by Keybox.get_or_create."""

    PHONE = "PHONE"
    CREDENTIAL = "CREDENTIAL"
    PRIVATE_KEY = "PRIVATE_KEY"
    BEARER = "BEARER"
    EMAIL = "EMAIL"
    SSN = "SSN"
    CREDIT_CARD = "CREDIT_CARD"
    BANK_ROUTING = "BANK_ROUTING"
    BANK_ACCOUNT = "BANK_ACCOUNT"
    IP_ADDRESS = "IP_ADDRESS"
    PERSON_NAME = "PERSON_NAME"
    ADDRESS = "ADDRESS"


__all__ = ["Keybox", "SecretType"]
